// T2.15 — scenario 03 (connection_pool_exhaustion, junior): FASE-2 CN-1, CN-2, CN-6, CN-7, DET.
// Every assertion reads telemetry generated by the engine with the scenario's own seed (SPEC §3.3):
// no expected value here is copied from the YAML text, except the parameters under test.
// The replay of referencePath against checkMitigations (CN-5, EN-6b) is T2.20.
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { accumulatedImpact, createSimulation, defaultShop, resolveFaults, toNdjson } from '@whodeployed/engine'
import type { MetricRecord, TelemetryView } from '@whodeployed/engine'
import { describe, expect, it } from 'vitest'
import { inRepertoire, toSimulationConfig } from '../../src/index.js'
import type { EngineRuntime, Scenario } from '../../src/index.js'
import { loadScenarioFile } from '../../src/node.js'

const engine: EngineRuntime = { resolveFaults, createSimulation, accumulatedImpact, systems: { 'default-shop': defaultShop } }

const here = dirname(fileURLToPath(import.meta.url))
const file = join(here, '..', '..', 'scenarios', '03-connection-pool-exhausted.yaml')
const scenario: Scenario = loadScenarioFile(file, engine)
const fault = scenario.faults[0]!
const target = fault.target
const poolSize = fault.params['poolSize'] as number
const leakPerTick = fault.params['leakPerTick'] as number
const alertTick = scenario.alert.tick

/** Telemetry of the scenario (fault + noise) up to `ticks`. */
function faulted(ticks = alertTick): TelemetryView {
  const sim = engine.createSimulation(toSimulationConfig(scenario, engine))
  sim.advance(ticks)
  return sim.telemetry()
}

/** Same seed and system, no fault and no noise: the baseline the trap is measured against. */
function baseline(ticks = alertTick): TelemetryView {
  const sim = engine.createSimulation({ ...toSimulationConfig(scenario, engine), faults: [], noise: [] })
  sim.advance(ticks)
  return sim.telemetry()
}

function aggregate(view: TelemetryView, component: string, tick: number): MetricRecord {
  const record = view.metricsOf(component, tick, tick).find((r) => r.instance === undefined)
  if (record === undefined) throw new Error(`no aggregate metric for ${component} at tick ${tick}`)
  return record
}

function instances(view: TelemetryView, component: string, tick: number): MetricRecord[] {
  return view.metricsOf(component, tick, tick).filter((r) => r.instance !== undefined)
}

describe('03: fields (CN-1, CN-2)', () => {
  it('is the junior campaign scenario 03 with a one-lesson teaches', () => {
    expect(scenario.id).toMatch(/^03-/)
    expect(scenario.level).toBe('junior')
    expect(scenario.testIncident).toBe(false)
    expect(scenario.teaches).not.toMatch(/\band\b/i)
    expect(scenario.trap.length).toBeGreaterThan(0)
    expect(scenario.impactBudget).toBeGreaterThanOrEqual(1)
    expect(scenario.review.keySignal.length).toBeGreaterThan(0)
  })

  it('has exactly one connection_pool_exhaustion fault with explicit target, startTick and params', () => {
    expect(scenario.faults).toHaveLength(1)
    expect(fault.kind).toBe('connection_pool_exhaustion')
    expect(target).toBe('payment')
    expect(Number.isInteger(fault.startTick)).toBe(true)
    expect(Object.keys(fault.params).sort()).toEqual(['acquireTimeoutMs', 'leakPerTick', 'poolSize'])
  })

  it('has noise (design rule from scenario 3 on) and no note that names the culprit', () => {
    expect(scenario.noise.length).toBeGreaterThanOrEqual(1)
    for (const event of scenario.noise) {
      expect(event.target).not.toBe(target)
      expect(event.note ?? '').not.toMatch(/payment|pool|connection|postgres|database|\bdb\b|leak/i)
    }
  })

  it('walks a referencePath made only of junior questions and actions (golden rule, SPEC §5)', () => {
    for (const step of scenario.referencePath) expect(inRepertoire('junior', step)).toBe(true)
  })

  it('lets restart be an effective mitigation: the reset pool does not refill inside [t+4, t+33] (ADR-012, ADR-013 §4)', () => {
    // After restart at t the leak restarts at te = t + 1 with s = 0, and the pool is exhausted
    // again once leakPerTick × (s + 1) >= poolSize. The last tick of the window is s = 32.
    expect(leakPerTick * (32 + 1) + 1).toBeLessThanOrEqual(poolSize)
  })
})

describe('03: the alert does not come before the symptom (CN-6)', () => {
  const view = faulted()

  it('fires at or after the fault start', () => {
    expect(alertTick).toBeGreaterThanOrEqual(fault.startTick)
  })

  it('alert text condition holds at alert.tick: gateway p95 > 1s', () => {
    expect(scenario.alert.text).toContain('gateway')
    expect(scenario.alert.text).toContain('p95')
    expect(scenario.alert.text).toContain('> 1s')
    expect(aggregate(view, 'gateway', alertTick).p95).toBeGreaterThan(1000)
  })

  it('every instance of the target holds poolSize connections at alert.tick', () => {
    const records = instances(view, target, alertTick)
    expect(records.length).toBe(defaultShop.services.find((s) => s.name === target)!.replicas)
    for (const r of records) expect(r.connections).toBe(poolSize)
  })

  it('the target serves >= 1 request in every tick of the signature window (seed exercised, R6)', () => {
    for (let tick = fault.startTick + 6; tick <= fault.startTick + 11; tick++) {
      const served = view.spansOf(target, tick).filter((s) => s.kind === 'server').length
      expect(served, `tick ${tick}`).toBeGreaterThanOrEqual(1)
    }
  })
})

describe('03: the trap exists in the telemetry (CN-7, SPEC §3.4)', () => {
  const view = faulted()
  const base = baseline()
  const gateway = aggregate(view, 'gateway', alertTick)
  const gatewayBase = aggregate(base, 'gateway', alertTick)
  const payment = aggregate(view, target, alertTick)
  const paymentBase = aggregate(base, target, alertTick)

  it('gateway p50 stays within 1.5x of the baseline while the target p95 is >= 3x', () => {
    expect(gateway.p50).toBeLessThanOrEqual(1.5 * gatewayBase.p50)
    expect(paymentBase.p95).toBeGreaterThan(0)
    expect(payment.p95).toBeGreaterThanOrEqual(3 * paymentBase.p95)
  })

  it('gateway error rate stays under 5%: the aggregate looks healthy', () => {
    expect(gateway.errorPct).toBeLessThan(5)
  })
})

describe('03: determinism (DET)', () => {
  it('the same seed gives byte-identical telemetry twice', () => {
    const ticks = alertTick + 2 * scenario.impactBudget
    expect(toNdjson(faulted(ticks).all())).toBe(toNdjson(faulted(ticks).all()))
  })
})
